    },
    {
      "text": "The amendment is in force from 2026-09-01 and applies on 2026-10-27.",
      "sources": [
        "R-12-r3-a1-4.4.1"
      ]
    }
  ]
}

{
  "status": "answered",
  "answer": "After bearing replacement, perform the vibration measurement within 8 hours after startup, at steady state no earlier than 30 minutes after startup. Record the result in the maintenance log and CMMS during the shift.",
